const chapters=[
['The curious engineer','NMIMS · MUMBAI','⌘','B.Tech at NMIMS MPSTME, Mumbai. Exploring data science, machine learning and AI—one question at a time.'],
['The scrapbook heart','BEYOND THE CODE','✿','Books, poetry, fashion, music, travel and cafés. Different kinds of curiosity, all on the same desk.'],
...window.portfolio.leadership.map((x,i)=>[x.place,x.role,['✦','★','↗','✳','❋'][i],x.role+(x.note?' · '+x.note:'')]),
['Q75 Signatures','CONTENT & COMMUNICATION','✎','Content Strategist · 2024–2026. Two years working on content strategy.'],
['Summer camps','VOLUNTEERING','☀','Summer-camp volunteer, working with children under 12.'],
['A note to myself','ALWAYS GROWING','❀','Keep learning. Keep making. Leave room for the unexpected.']
];
const root=document.getElementById('matchboxes');chapters.forEach(([title,kicker,motif,body],i)=>{const button=document.createElement('button');button.className='matchbox';button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open '+title);const tray=document.createElement('span');tray.className='match-tray';tray.id='chapter-'+i;tray.setAttribute('aria-hidden','true');const heading=document.createElement('strong');heading.textContent=title;const copy=document.createElement('span');copy.textContent=body;tray.append(heading,copy);const cover=document.createElement('span');cover.className='match-cover';const top=document.createElement('small');top.textContent=kicker;const symbol=document.createElement('span');symbol.className='match-motif';symbol.setAttribute('aria-hidden','true');symbol.textContent=motif;const name=document.createElement('strong');name.textContent=title;const foot=document.createElement('small');foot.className='match-action';foot.textContent='SLIDE TO DISCOVER ↑';cover.append(top,symbol,name,foot);button.append(tray,cover);button.setAttribute('aria-controls',tray.id);button.onclick=()=>{const opened=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(opened));button.setAttribute('aria-label',(opened?'Close ':'Open ')+title);tray.setAttribute('aria-hidden',String(!opened));cover.setAttribute('aria-hidden',String(opened));button.classList.toggle('is-open',opened)};(i>=2&&i<=6?document.getElementById('journey-matchboxes'):i===7||i===8?document.getElementById('people-matchboxes'):root).append(button)});
const flip=document.querySelector('.name-flip');flip.onclick=()=>{const active=flip.getAttribute('aria-pressed')!=='true';flip.setAttribute('aria-pressed',String(active));flip.setAttribute('aria-label',active?'Flip photograph back to Bhoomi Kothari’s name':'Flip name card to see Bhoomi’s photograph');flip.querySelector('.flip-front').setAttribute('aria-hidden',String(active));flip.querySelector('.flip-back').setAttribute('aria-hidden',String(!active));document.querySelector('.flip-hint').textContent=active?'Bhoomi Kothari · tap the photo to flip back ↻':'Tap my name · a different moment with every flip ↻'};
